/* Trading workspace: forms keep their state until a successful atomic server write. */
(()=>{'use strict';
const tabs=new Set(['purchases','stock','sales','finance','staff','customers','reports','setup']);
const kinds={purchase_order:'Замовлення постачальнику',receipt:'Надходження',opening:'Початкові залишки',sale:'Продаж',customer_return:'Повернення покупця',supplier_return:'Повернення постачальнику',transfer:'Переміщення',writeoff:'Списання',inventory:'Інвентаризація',production:'Виробництво',payment:'Оплата боргу',expense:'Витрата',cash_opening:'Початкові кошти',payroll:'Нарахування зарплати',payroll_payment:'Виплата зарплати / аванс',customer_order:'Замовлення покупця',debt_opening:'Початкова заборгованість',cash_transfer:'Переміщення коштів'};
const status={draft:'Чернетка',posted:'Проведено',reversed:'Скасовано'};
const groups={purchases:['purchase_order','receipt','supplier_return'],stock:['opening','transfer','writeoff','inventory','production'],sales:['sale','customer_return','customer_order'],finance:['payment','expense','cash_opening','debt_opening','cash_transfer'],staff:['payroll','payroll_payment']};
const roles={owner:[...tabs],manager:['purchases','stock','sales','finance','customers','reports'],cashier:['sales','stock','customers'],warehouse:['purchases','stock'],accountant:['finance','staff','customers','reports']};
const lineKinds=new Set(['purchase_order','receipt','opening','sale','customer_return','supplier_return','transfer','writeoff','inventory','production','customer_order']);
const priceKinds=new Set(['purchase_order','receipt','opening','sale','customer_order','inventory']);
const roleKinds={owner:Object.keys(kinds),manager:Object.keys(kinds).filter(k=>!['payroll','payroll_payment','cash_opening','debt_opening'].includes(k)),cashier:['sale','customer_return','customer_order'],warehouse:['purchase_order','receipt','opening','supplier_return','transfer','writeoff','inventory','production'],accountant:['payment','expense','cash_opening','payroll','payroll_payment','debt_opening','cash_transfer']};
let current=null,generation=0,E=null,P=[],C={},csrf='',listPage=1,filterStatus='',filterStore='',search='',stockData=null;
const main=()=>document.getElementById('main');
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const amount=n=>new Intl.NumberFormat('uk-UA',{minimumFractionDigits:2,maximumFractionDigits:2}).format(Number(n||0));
const quantity=n=>new Intl.NumberFormat('uk-UA',{maximumFractionDigits:3}).format(Number(n||0));
const date=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/Kyiv',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const name=(list,id)=>E?.[list]?.find(x=>String(x.id)===String(id))?.name||'—';
const option=(values,selected='',empty='Виберіть…')=>`<option value="">${esc(empty)}</option>`+values.map(x=>`<option value="${esc(x.id)}" ${String(x.id)===String(selected)?'selected':''}>${esc(x.name)}</option>`).join('');
const field=(label,input,cls='')=>`<label class="${cls}">${label}${input}</label>`;
const select=(key,values,selected='',required=false,empty)=>`<select name="${key}" ${required?'required':''}>${option(values,selected,empty)}</select>`;
const input=(key,value='',type='text',attrs='')=>`<input name="${key}" value="${esc(value)}" type="${type}" ${attrs}>`;
const num=(key,value='',step='0.01',attrs='')=>input(key,value,'number',`min="0" step="${step}" inputmode="decimal" ${attrs}`);
const button=(text,act,attrs='',primary=false)=>`<button class="btn ${primary?'':'soft'}" type="button" data-trade="${act}" ${attrs}>${text}</button>`;
const table=(headers,rows,empty='Поки немає записів.')=>rows.length?`<div class="trade-table-wrap"><table class="trade-table"><thead><tr>${headers.map(h=>`<th scope="col">${h}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map((c,i)=>`<td data-label="${headers[i]}"><div class="trade-cell">${c}</div></td>`).join('')}</tr>`).join('')}</tbody></table></div>`:`<div class="trade-empty">${empty}</div>`;
const cards=values=>`<div class="trade-grid">${values.map(([title,value,hint])=>`<div class="trade-card"><span class="muted">${title}</span><strong>${value}</strong>${hint?`<p class="muted">${hint}</p>`:''}</div>`).join('')}</div>`;
async function api(path,method='GET',value){if(!csrf){const r=await fetch('/api/state');if(r.status===401){location.href='/';throw Error('Сеанс завершився.');}csrf=(await r.json()).csrf;}const r=await fetch('/api/erp/'+path,{method,credentials:'same-origin',headers:{'Content-Type':'application/json','X-CSRF-Token':csrf},body:value===undefined?undefined:JSON.stringify(value)});if(r.status===401){location.href='/';throw Error('Сеанс завершився.');}let result;try{result=await r.json();}catch{throw Error('Сервер не відповідає. Повторіть спробу.');}if(!r.ok)throw Error(result.error||'Не вдалося виконати дію.');return result;}
async function load(){const [state,legacy]=await Promise.all([api('state'),fetch('/api/state').then(r=>r.json())]);E=state;P=(legacy.data?.products||[]).map(p=>({id:p.id,...p.data}));csrf=legacy.csrf;C=legacy.data?.['settings/main']||{};applyRole();}
function applyRole(){document.querySelectorAll('.tab').forEach(a=>{if(tabs.has(a.dataset.tab))a.hidden=!roles[E.role]?.includes(a.dataset.tab);});if(E.role!=='owner'){document.querySelector('[data-workspace="development"]').hidden=true;document.querySelectorAll('.tab[data-tab="expenses"],.tab[data-tab="ideas"],.tab[data-tab="tasks"],.tab[data-tab="devOverview"]').forEach(x=>x.hidden=true);}}
function errorPanel(error){main().innerHTML=`<section class="panel"><p class="trade-alert error" role="alert">${esc(error.message)}</p>${button('Повторити','refresh')}</section>`;}
function alert(text){return `<div class="trade-alert">${text}</div>`;}
function toolbar(actions=''){return `<div class="trade-toolbar"><h3>Документи</h3>${field('Магазин',select('filterStore',E.stores,filterStore,false,'Усі магазини'))}${field('Стан',select('filterStatus',Object.entries(status).map(([id,name])=>({id,name})),filterStatus,false,'Усі стани'))}${actions}${button('Оновити','refresh')}</div>`;}
const actionsFor=tab=>(groups[tab]||[]).filter(k=>roleKinds[E.role]?.includes(k)).map(k=>button(kinds[k],'new-voucher',`data-kind="${k}"`,k==='sale'||k==='receipt')).join('');
async function vouchersPanel(extra=''){const kind=(groups[current]||[]).filter(k=>roleKinds[E.role]?.includes(k)).join(',');if(!kind)return '';const data=await api(`vouchers?kind=${kind}&page=${listPage}&status=${filterStatus}&store=${filterStore}`);return `<section class="panel">${extra}${toolbar(actionsFor(current))}${voucherTable(data.items)}<div class="trade-pagination"><span class="muted">${data.total?`${(listPage-1)*30+1}–${Math.min(listPage*30,data.total)} із ${data.total}`:'0 документів'}</span><div class="row">${button('Назад','prev',''+(listPage===1?'disabled':''))}${button('Далі','next',listPage*30>=data.total?'disabled':'')}</div></div></section>`;}
function voucherTable(items){return table(['Документ','Дата','Магазин','Контрагент / працівник','Сума','Стан','Дії'],items.map(v=>[`${esc(kinds[v.kind])}<span class="muted">№ ${v.number}</span>`,esc(v.date),esc(name('stores',v.store)),esc(v.employee?name('employees',v.employee):name('parties',v.party)),amount(v.total)+' грн',`<span class="trade-status ${v.status}">${status[v.status]}</span>`,button('Відкрити','view',`data-id="${v.id}"`)]));}
async function draw(){const token=++generation,tab=current;if(!E)await load();if(!roles[E.role]?.includes(tab))throw Error('Цей розділ недоступний вашій ролі.');let html='';if(tab==='purchases')html=await vouchersPanel(alert('Замовлення фіксує намір закупівлі. Товарний залишок і борг постачальнику з’являються після проведення надходження.'));
if(tab==='stock'){stockData=await api('stock');html=stockView()+await vouchersPanel();}
if(tab==='sales')html=shiftView()+await vouchersPanel(alert(E.fiscal_required?'Для проведення продажу потрібен номер чека, виданого вашим ПРРО.':'Продажі записуються в облік. Автоматична фіскалізація ще не підключена; чек ПРРО можна зазначити вручну.'));
if(tab==='finance'){const [r,l]=await Promise.all([api('report'),api('ledger')]);html=`<section class="panel"><div class="trade-panel-head"><h3>Грошові рахунки</h3>${E.role==='owner'?button('Додати рахунок','entity', 'data-entity="accounts"'):''}</div>${cards(E.accounts.map(a=>[esc(a.name),amount(a.balance)+' грн',esc(name('stores',a.store_id))]))}<h3 class="trade-section-title">Заборгованість</h3>${debtTable(r.debts)}<h3 class="trade-section-title">Останні грошові операції</h3>${table(['Дата','Рахунок','Операція','Сума','Дії'],l.entries.slice(0,30).map(x=>[esc(x.date),esc(x.account),esc(kinds[x.kind])+(x.reversal?' · скасування':''),amount(x.amount)+' грн',button('Документ','view',`data-id="${x.voucher}"`)]))}</section>`+await vouchersPanel(alert('Фактичні витрати створюють рух коштів. Планові місячні витрати зі старого розділу залишаються бюджетом і не потрапляють у цей облік.'));}
if(tab==='staff')html=staffView()+await vouchersPanel();
if(tab==='customers')html=customersView();
if(tab==='reports'){const r=await api('report');html=reportView(r);}
if(tab==='setup')html=setupView();
if(token!==generation||tab!==current)return;main().innerHTML=html;applyRole();}
function stockView(){const totals=stockData.totals.filter(x=>(!filterStore||E.warehouses.find(w=>w.id===x.warehouse)?.store_id===Number(filterStore))&&(!search||x.name.toLocaleLowerCase('uk').includes(search.toLocaleLowerCase('uk'))));const low=totals.filter(x=>x.low),exp=stockData.lots.filter(x=>x.expiry&&x.expiry<=new Date(Date.now()+7*86400000).toISOString().slice(0,10));return `<section class="panel"><div class="trade-toolbar"><h3>Залишки товарів</h3><label class="trade-search">Пошук<input name="stockSearch" value="${esc(search)}" type="search" placeholder="Назва товару"></label>${button('Вивантажити CSV','stock-csv')}${['owner','manager'].includes(E.role)?button('Оновити контроль','alerts'):''}${['owner','manager','warehouse'].includes(E.role)?button('Рецептури','recipe'):''}</div>${cards([['Вартість залишків',amount(totals.reduce((s,x)=>s+Number(x.value||0),0))+' грн'],['Нижче мінімуму',low.length],['Партій до контролю',exp.length,'Термін минув або спливає за 7 днів']])}${!stockData.lots.length?alert('Початкові залишки ще не введені. Проведіть документ «Початкові залишки» або перше надходження. Каталог товарів сам по собі не створює складських кількостей.'):''}<h3 class="trade-section-title">Товари за складами</h3>${table(['Товар','Склад','Кількість','Доступно','Вартість','Контроль'],totals.map(x=>[`<span class="table-name">${esc(x.name)}</span>`,esc(name('warehouses',x.warehouse)),quantity(x.quantity)+' '+esc(x.unit),quantity(x.available)+' '+esc(x.unit),E.role==='cashier'?'—':amount(x.value)+' грн',x.low?'<span class="trade-status draft">Поповнити</span>':'—']))}<details data-disclosure="stock-lots"><summary>Партії та терміни придатності</summary>${table(['Товар','Партія','Склад','Термін','Кількість'],stockData.lots.map(x=>[esc(x.name),esc(x.lot),esc(name('warehouses',x.warehouse)),x.expiry?`<span class="${x.expired?'trade-error':''}">${esc(x.expiry)}</span>`:'Без терміну',quantity(x.quantity)+' '+esc(x.unit)]))}</details></section>`;}
function shiftView(){return `<section class="panel"><div class="trade-panel-head"><h3>Касові зміни</h3>${button('Відкрити зміну','shift-open')}</div>${table(['Зміна','Магазин','Каса','Працівник','Стан','Дії'],E.shifts.slice(0,12).map(s=>[`№ ${s.id}<span class="muted">${new Date(s.opened_at).toLocaleString('uk-UA')}</span>`,esc(name('stores',s.store_id)),esc(name('accounts',s.account_id)),esc(name('employees',s.employee_id)),s.closed_at?`Закрита<span class="muted">Різниця ${amount(Number(s.counted_cash)-Number(s.expected_cash))} грн</span>`:'Відкрита',s.closed_at?'—':button('Закрити','shift-close',`data-id="${s.id}"`)]))}</section>`;}
function staffView(){return `<section class="panel"><div class="trade-panel-head"><h3>Працівники</h3>${E.role==='owner'?button('Додати працівника','entity','data-entity="employees"'):''}</div>${alert('Ставка за зміну + відсоток від виторгу касової зміни. У табелі зберігаються умови конкретної зміни. Нарахування й виплата — окремі документи; аванс зменшує суму до виплати. Податки та звітність до ДПС тут не розраховуються.')}${table(['Працівник','Магазин','Ставка за зміну','Відсоток','До виплати','Дії'],E.employees.map(e=>[esc(e.name)+(e.active?'':'<span class="muted">Неактивний</span>'),esc(name('stores',e.store_id)),amount(e.shift_rate)+' грн',quantity(e.bonus_percent)+' %',amount(E.payroll_debts.find(x=>x.employee===e.id)?.amount)+' грн',E.role==='owner'?button('Умови','entity',`data-entity="employees" data-id="${e.id}"`):'—']))}<div class="trade-panel-head trade-section-title"><h3>Табель змін</h3>${button('Відмітити зміну','work-shift')}</div>${table(['Дата','Працівник','Змін','Умови','Нараховано','Стан'],E.work_shifts.map(s=>[esc(s.date),esc(name('employees',s.employee_id)),quantity(s.units),`${amount(s.shift_rate)} грн + ${quantity(s.bonus_percent)} %`,amount(s.accrued)+' грн',s.payroll_id?button('Нарахування','view',`data-id="${s.payroll_id}"`):button('Редагувати','work-shift',`data-id="${s.id}"`)]))}</section>`;}
function customersView(){return `<section class="panel"><div class="trade-toolbar"><h3>Клієнтська база</h3><label class="trade-search">Пошук<input name="partySearch" type="search" value="${esc(search)}" placeholder="Ім’я або телефон"></label>${E.role!=='cashier'?button('Додати клієнта','entity','data-entity="parties" data-party-kind="customer"'):''}</div>${table(['Клієнт','Телефон','Email','Примітка','Дії'],E.parties.filter(x=>x.kind==='customer'&&(`${x.name} ${x.phone}`.toLowerCase().includes(search.toLowerCase()))).map(c=>[esc(c.name),esc(c.phone),esc(c.email),esc(c.notes),`<div class="row">${button('Історія','customer-history',`data-id="${c.id}"`)}${E.role!=='cashier'?button('Редагувати','entity',`data-entity="parties" data-id="${c.id}"`):''}</div>`]))}</section>`;}
function debtTable(debts){return table(['Документ','Контрагент','Сума боргу','Термін','Дії'],debts.map(d=>[`№ ${String(d.voucher).padStart(6,'0')}<span class="muted">${d.kind==='receipt'?'Ми винні':'Нам винні'}</span>`,esc(d.party),amount(d.amount)+' грн',`${esc(d.due_date||'Не задано')}${d.overdue?'<span class="trade-error">Прострочено</span>':''}`,button('Оплатити','pay-debt',`data-id="${d.voucher}"`)]));}
function reportView(r){return `<section class="panel"><form id="tradeReportForm" class="trade-toolbar">${field('З',input('from',r.from,'date','required'))}${field('По',input('to',r.to,'date','required'))}${field('Магазин',select('store',E.stores,filterStore,false,'Усі магазини'))}<button class="btn" type="submit">Показати</button>${button('Вивантажити CSV','report-csv')}</form><div id="tradeReportResult">${reportContent(r)}</div></section>`;}
let lastReport=null;
function reportContent(r){lastReport=r;return '<div class="trade-report-cards">'+cards([['Виторг',amount(r.revenue)+' грн','Продажі мінус повернення'],['Собівартість продажів',amount(r.cogs)+' грн','За фактичним складським рухом'],['Валовий прибуток',amount(r.gross_profit)+' грн'],['Операційний результат',amount(r.profit)+' грн','Після витрат, зарплати та складських коригувань'],['Витрати / зарплата',amount(Number(r.expenses)+Number(r.payroll))+' грн'],['Чистий рух коштів',amount(r.cash_net)+' грн','Без початкових залишків']])+'</div>'+`<p class="trade-caption">Закупівля створює запаси; її собівартість потрапляє у результат під час продажу. Кредитні продажі враховуються у виторгу, а оплата — у русі коштів. Результат управлінський, до податків. Списання: ${amount(r.writeoffs)} грн; інвентаризаційне коригування: ${amount(r.inventory_adjustment)} грн.</p><h3 class="trade-section-title">Магазини</h3>${table(['Магазин','Виторг','Валовий прибуток'],r.by_store.map(x=>[esc(x.name),amount(x.revenue)+' грн',amount(x.gross_profit)+' грн']))}<h3 class="trade-section-title">Поточна заборгованість</h3>${debtTable(r.debts)}`;}
function setupView(){return `<section class="panel">${alert('Перейменуйте основний магазин і додайте реальні склади та рахунки. Початкові товарні й грошові залишки вводяться документами — жодних кількостей з каталогу не припускаємо.')}${['stores','warehouses','accounts','parties'].map(key=>`<div class="trade-panel-head trade-section-title"><h3>${({stores:'Магазини',warehouses:'Склади',accounts:'Рахунки',parties:'Постачальники та клієнти'})[key]}</h3>${button('Додати','entity',`data-entity="${key}"`)}</div>${table(['Назва','Тип / магазин','Дії'],E[key].map(x=>[esc(x.name),esc(x.store_id?name('stores',x.store_id):({supplier:'Постачальник',customer:'Покупець',cash:'Готівка',bank:'Банк',terminal:'Термінал'})[x.kind]||'Магазин'),button('Редагувати','entity',`data-entity="${key}" data-id="${x.id}"`)]))}`).join('')}<h3 class="trade-section-title">Контроль обліку</h3><div class="trade-subnav">${button('Користувачі та ролі','users')}${button('Журнал змін','audit')}${button('Обліковий період','period')}${button('Налаштування ПРРО','fiscal')}</div><p class="trade-caption">Закрито по: ${esc(E.closed_through||'період відкритий')}. Режим чеків: ${E.fiscal_required?'обов’язковий номер чека ПРРО':'ручне зазначення; автоматичне ПРРО не підключене'}.</p></section>`;}
let dialog=null,restoreFocus=null;
function modal(title,html,foot='',small=false){restoreFocus=document.activeElement;if(dialog?.open)dialog.close();if(dialog)dialog.remove();dialog=document.createElement('dialog');dialog.className='trade-dialog'+(small?' small':'');dialog.setAttribute('aria-labelledby','tradeDialogTitle');dialog.innerHTML=`<div class="trade-dialog-head"><h2 id="tradeDialogTitle">${esc(title)}</h2>${button('Закрити','close','aria-label="Закрити вікно"')}</div><div class="trade-dialog-body">${html}<p id="tradeFormError" class="trade-error" role="alert"></p></div>${foot?`<div class="trade-dialog-foot">${foot}</div>`:''}`;document.body.append(dialog);dialog.addEventListener('input',()=>dialog.dataset.dirty='1');dialog.addEventListener('change',()=>dialog.dataset.dirty='1');dialog.addEventListener('cancel',e=>{if(dialog.dataset.dirty==='1'&&!confirm('Закрити форму без збереження змін?'))e.preventDefault();});dialog.addEventListener('close',()=>restoreFocus?.isConnected&&restoreFocus.focus());dialog.showModal();return dialog;}
function formError(e){const el=dialog?.querySelector('#tradeFormError');if(el){el.textContent=e.message;el.scrollIntoView({block:'nearest'});}else errorPanel(e);}
async function submit(form,fn){const buttons=[...form.querySelectorAll('button[type=submit]')];buttons.forEach(b=>b.disabled=true);dialog.querySelector('#tradeFormError').textContent='';try{await fn(Object.fromEntries(new FormData(form)));dialog.dataset.dirty='';dialog.close();await load();await draw();}catch(e){formError(e);}finally{buttons.forEach(b=>b.disabled=false);}}
function entityForm(key,id,partyKind){const x=E[key].find(x=>String(x.id)===String(id))||{},titles={stores:'Магазин',warehouses:'Склад',parties:'Контрагент',accounts:'Грошовий рахунок',employees:'Працівник'};let html=field('Назва / ім’я',input('name',x.name||'','text','required maxlength="160"'));if(['warehouses','accounts','employees'].includes(key))html+=field('Магазин',select('store',E.stores,x.store_id||filterStore||E.stores[0]?.id,true));if(key==='parties')html+=field('Тип',select('kind',[{id:'supplier',name:'Постачальник'},{id:'customer',name:'Клієнт'}],x.kind||partyKind||'supplier',true))+field('Телефон',input('phone',x.phone||'','tel'))+field('Email',input('email',x.email||'','email'))+field('Примітка',`<textarea name="notes" rows="3">${esc(x.notes||'')}</textarea>`,'wide');if(key==='accounts')html+=field('Тип рахунку',select('kind',[{id:'cash',name:'Готівка'},{id:'bank',name:'Банк'},{id:'terminal',name:'Термінал'}],x.kind||'cash',true));if(key==='employees')html+=field('Оплата за зміну, грн',num('shift_rate',x.shift_rate||0))+field('Відсоток від виторгу, %',num('bonus_percent',x.bonus_percent||0,'0.001','max="100"'))+field('База відсотка',select('bonus_basis',[{id:'store',name:'Виторг магазину за касову зміну'},{id:'personal',name:'Особисті продажі'},{id:'profit',name:'Валовий прибуток за зміну'}],x.bonus_basis||'store',true));if(['employees','parties','stores'].includes(key))html+=field('Стан',select('active',[{id:'yes',name:'Активний'},{id:'no',name:'Неактивний'}],x.active===false?'no':'yes',true));const d=modal(titles[key],`<form id="tradeEntityForm"><div class="trade-form-grid">${html}</div><div class="row trade-section-title"><button class="btn" type="submit">Зберегти</button></div></form>`,'',true);d.querySelector('form').onsubmit=e=>{e.preventDefault();submit(e.target,value=>api('entities/'+key,'POST',{...value,id:x.id,active:value.active!=='no'}));};}
let editing=null;
function productOptions(selected){return option(P.map(p=>({id:p.id,name:p.name+(p.promotion?' · Акція':'')+' · '+(p.unit||'шт')})),selected,'Виберіть товар');}
function lineMarkup(kind,line={}){return `<div class="trade-line ${kind==='sale'?'sale-line':''}">${field('Товар',`<select data-line="product" required>${productOptions(line.product)}</select>`,'line-product')}${field(kind==='inventory'?'Пораховано':'Кількість',`<input data-line="quantity" type="number" inputmode="decimal" min="${kind==='inventory'?0:0.001}" step="0.001" value="${esc(line.quantity??1)}" required>`)}${field(kind==='inventory'?'Собівартість надлишку':'Ціна, грн',`<input data-line="price" type="number" inputmode="decimal" min="0" step="0.0001" value="${esc(line.price??0)}" ${!priceKinds.has(kind)?'readonly':''}>`)}${kind==='sale'?'<label hidden>Партія<input data-line="lot" value=""></label>':field('Партія',`<input data-line="lot" value="${esc(line.lot||'')}" maxlength="80">`)}${kind==='sale'?'<label hidden>Придатний до<input data-line="expiry" value=""></label>':field('Придатний до',`<input data-line="expiry" type="date" value="${esc(line.expiry||'')}">`)}${button('×','remove-line','aria-label="Видалити товарний рядок" class="remove-line"')}</div>`;}
function paymentMarkup(p={}){return `<div class="trade-payment-row">${field('Рахунок',`<select data-payment="account">${option(E.accounts.filter(a=>a.store_id===Number(editing.store)),p.account)}</select>`)}${field('Сума, грн',`<input data-payment="amount" type="number" min="0.01" step="0.01" value="${esc(p.amount||'')}">`)}${button('×','remove-payment','aria-label="Видалити спосіб оплати"')}</div>`;}
function updateTotal(){const rows=[...dialog.querySelectorAll('.trade-line')];const scaled=(text,places)=>{const m=String(text||'0').replace(/^\./,'0.').match(/^(\d+)(?:\.(\d*))?$/);if(!m||m[2]?.length>places)return 0n;return BigInt(m[1])*10n**BigInt(places)+BigInt((m[2]||'').padEnd(places,'0')||'0');};const cents=rows.reduce((s,r)=>s+(scaled(r.querySelector('[data-line=quantity]').value,3)*scaled(r.querySelector('[data-line=price]').value,4)+50000n)/100000n,0n);let total=Number(cents)/100;if(editing.kind==='receipt')total+=Number(dialog.querySelector('[name=additional_cost]')?.value||0);const target=dialog.querySelector('#tradeDraftTotal');if(target)target.textContent=amount(total)+' грн';return total;}
function syncDocumentFields(){const form=dialog.querySelector('#tradeVoucherForm');if(!form)return;editing.store=form.elements.store.value;const st=Number(editing.store);form.elements.warehouse&&(form.elements.warehouse.innerHTML=option(E.warehouses.filter(w=>w.store_id===st),editing.warehouse||E.warehouses.find(w=>w.store_id===st)?.id));form.elements.account&&(form.elements.account.innerHTML=option(E.accounts.filter(a=>a.store_id===st),editing.account||E.accounts.find(a=>a.store_id===st)?.id));form.elements.employee&&(form.elements.employee.innerHTML=option(E.employees.filter(a=>a.store_id===st&&a.active),editing.employee));form.elements.shift&&(form.elements.shift.innerHTML=option(E.shifts.filter(s=>s.store_id===st&&!s.closed_at).map(s=>({id:s.id,name:`Зміна № ${s.id} · ${name('accounts',s.account_id)}`})),editing.shift));dialog.querySelectorAll('[data-payment=account]').forEach(a=>{const old=a.value;a.innerHTML=option(E.accounts.filter(a=>a.store_id===st),old);});}
async function voucherForm(kind,existing=null,prefill={}){editing=existing?structuredClone(existing):{kind,date:date(),store:Number(filterStore)||E.stores[0]?.id,lines:[],payload:{},...prefill};const v=editing;v.idempotency_key=v.idempotency_key||crypto.randomUUID();const isLines=lineKinds.has(kind),paying=['sale','customer_return','supplier_return'].includes(kind);let html=field('Дата',input('date',v.date,'date','required'))+field('Магазин',select('store',E.stores,v.store,true));if(isLines)html+=field('Склад',select('warehouse',E.warehouses.filter(w=>w.store_id===Number(v.store)),v.warehouse||E.warehouses.find(w=>w.store_id===Number(v.store))?.id,true));if(kind==='cash_transfer')html+=field('На рахунок',select('target_account',E.accounts,v.payload?.target_account,true));if(kind==='debt_opening')html+=field('Контрагент',select('party',E.parties,v.party,true))+field('Сума боргу, грн',num('amount',v.total||v.amount||'','0.01','required min="0.01"'));if(kind==='transfer')html+=field('Склад призначення',select('target',E.warehouses,v.target,true));if(['purchase_order','receipt','supplier_return','sale','customer_return','customer_order'].includes(kind))html+=field(['receipt','purchase_order','supplier_return'].includes(kind)?'Постачальник':'Покупець',select('party',E.parties.filter(p=>p.active&&p.kind===(['receipt','purchase_order','supplier_return'].includes(kind)?'supplier':'customer')),v.party,['receipt','purchase_order','supplier_return','customer_order'].includes(kind)));if(['sale','payroll','payroll_payment'].includes(kind))html+=field('Працівник',select('employee',E.employees.filter(e=>(e.active||kind!=='sale')&&e.store_id===Number(v.store)),v.employee,kind!=='sale'));if(['payment','expense','cash_opening','payroll_payment','cash_transfer'].includes(kind))html+=field('Грошовий рахунок',select('account',E.accounts.filter(a=>a.store_id===Number(v.store)),v.account||E.accounts.find(a=>a.store_id===Number(v.store))?.id,true))+field('Сума, грн',num('amount',v.total||v.amount||'','0.01','required min="0.01"'));if(kind==='sale')html+=field('Касова зміна',select('shift',E.shifts.filter(s=>s.store_id===Number(v.store)&&!s.closed_at).map(s=>({id:s.id,name:`№ ${s.id} · ${name('accounts',s.account_id)}`})),v.shift||E.shifts.find(s=>s.store_id===Number(v.store)&&!s.closed_at)?.id))+field('Номер чека ПРРО',input('fiscal_ref',v.payload?.fiscal_ref||'','text',E.fiscal_required?'required':''));if(['sale','customer_order','receipt','purchase_order','debt_opening'].includes(kind))html+=field('Оплатити до',input('due_date',v.payload?.due_date||'','date'));if(kind==='receipt')html+=field('Додаткові витрати постачальника, грн',num('additional_cost',v.payload?.additional_cost||0));if(kind==='expense')html+=field('Стаття витрат',select('category',['Оренда','Комунальні','Логістика','Обслуговування','Маркетинг','Податки','Інше'].map(x=>({id:x,name:x})),v.payload?.category||'Інше',true));
const refKind={receipt:'purchase_order',sale:'customer_order',customer_return:'sale',supplier_return:'receipt',payment:'receipt,sale,debt_opening'}[kind];let references=[];if(refKind){references=(await api(`vouchers?kind=${refKind}&status=posted&store=${v.store}`)).items; if(v.reference&&!references.some(x=>x.id===Number(v.reference)))references.push(await api('vouchers/'+v.reference));html+=field(kind==='payment'?'Документ для оплати':'Пов’язаний документ',select('reference',references.map(r=>({id:r.id,name:`№ ${r.number} · ${kinds[r.kind]} · ${amount(r.total)} грн`})),v.reference,['payment','customer_return','supplier_return'].includes(kind)));}
html+=field('Примітка',`<textarea name="note" rows="2" maxlength="4000">${esc(v.note||'')}</textarea>`,'wide');let extra='';if(isLines)extra=`<fieldset><legend>${kind==='production'?'Готовий товар':'Товарні рядки'}</legend>${kind==='inventory'?alert('Кількість — фактично порахований повний залишок товару на складі. Для надлишку вкажіть собівартість; нестача оцінюється за обліковою вартістю.'):''}${kind==='production'?alert('Списання інгредієнтів за збереженою рецептурою на одну одиницю готового товару. Рецептуру можна налаштувати зі складського розділу.'):''}<div id="tradeLines" class="trade-lines">${(v.lines.length?v.lines:[{}]).map(l=>lineMarkup(kind,l)).join('')}</div>${kind!=='production'?button('Додати товар','add-line'):''}${['receipt','opening','inventory'].includes(kind)?button('Завантажити CSV','import-lines')+button('Шаблон CSV','lines-template'):''}${kind==='sale'?`<div class="trade-barcode">${field('Штрихкод або точна назва',input('barcode','','search','autocomplete="off"'))}${button('Додати за штрихкодом','barcode')}</div><p class="trade-caption">Ціну або знижку можна змінити в рядку. Ознака «Акція» показується у назві товару.</p>`:''}</fieldset>`;if(paying)extra+=`<fieldset><legend>${kind==='sale'?'Оплата':'Повернення коштів'}</legend><div id="tradePayments">${(v.payload?.payments||[]).map(paymentMarkup).join('')}</div>${button('Додати спосіб оплати','add-payment')}${kind==='sale'?button('Оплатити всю суму','full-payment'):''}<p class="trade-caption">${kind==='sale'?'Для готівки оберіть відкриту касову зміну. Часткова оплата доступна для вибраного покупця.':'Оплачену частину потрібно повернути, неоплачена зменшує борг. Сервер перевірить суму.'}</p></fieldset>`;if(kind==='payroll')extra+=`<fieldset><legend>Відпрацьовані зміни</legend><div id="tradePayrollShifts" class="trade-checkbox-list"></div></fieldset>`;
const d=modal(`${v.id?'Редагування: ':'Новий документ: '}${kinds[kind]}`,`<form id="tradeVoucherForm"><div class="trade-form-grid">${html}</div>${extra}</form>`,`<strong id="tradeDraftTotal" class="trade-total"></strong><button class="btn soft" type="submit" form="tradeVoucherForm" name="action" value="draft">Зберегти чернетку</button><button class="btn" type="submit" form="tradeVoucherForm" name="action" value="post">Зберегти й провести</button>`);const form=d.querySelector('form');if(kind==='sale'){const details=document.createElement('details');details.className='trade-extra';details.innerHTML='<summary>Додаткові реквізити</summary><div class="trade-form-grid"></div>';for(const key of ['note','due_date','reference',...(!E.fiscal_required?['fiscal_ref']:[])]){const label=form.querySelector(`[name=${key}]`)?.closest('label');if(label)details.querySelector('div').append(label);}form.querySelector('fieldset')?.before(details);}updateTotal();const payrollShifts=()=>{const e=form.elements.employee?.value,target=d.querySelector('#tradePayrollShifts');if(target)target.innerHTML=E.work_shifts.filter(s=>String(s.employee_id)===String(e)&&!s.payroll_id).map(s=>`<label><input type="checkbox" name="shift_ids" value="${s.id}" ${(v.payload?.shift_ids||[]).map(String).includes(String(s.id))?'checked':''}>${esc(s.date)} · ${quantity(s.units)} зміна · ${amount(s.shift_rate)} грн + ${quantity(s.bonus_percent)} %</label>`).join('')||'<p class="muted">Немає відпрацьованих змін без нарахування.</p>';};payrollShifts();form.addEventListener('keydown',e=>{if(e.target.name==='barcode'&&e.key==='Enter'){e.preventDefault();act('barcode',e.target).catch(formError);}});form.addEventListener('input',updateTotal);form.addEventListener('change',async e=>{try{if(e.target.name==='store'){editing.warehouse=null;editing.account=null;editing.employee=null;editing.shift=null;syncDocumentFields();}if(e.target.name==='employee')payrollShifts();if(e.target.dataset.line==='product'){const p=P.find(p=>p.id===e.target.value),row=e.target.closest('.trade-line');if(p){row.querySelector('[data-line=price]').value=['sale','customer_order'].includes(kind)?retailPrice(p):p.cost||0;row.querySelector('[data-line=lot]').value='';updateTotal();}}if(e.target.name==='reference'&&e.target.value){const ref=await api('vouchers/'+e.target.value);form.elements.party&&(form.elements.party.value=ref.party||'');if(kind==='payment'){form.elements.amount.value=ref.outstanding||ref.total;}else{const remaining=ref.lines.filter(l=>Number(l.remaining??l.quantity)>0).map(l=>({...l,quantity:l.remaining??l.quantity}));d.querySelector('#tradeLines').innerHTML=remaining.map(l=>lineMarkup(kind,{...l,lot:'',expiry:''})).join('');if(['customer_return','supplier_return'].includes(kind)){const repay=Math.max(0,Number(ref.total)-Number(ref.outstanding||0));d.querySelector('#tradePayments').innerHTML=repay>0?paymentMarkup({account:E.accounts.find(a=>a.store_id===Number(v.store))?.id,amount:Math.min(Number(ref.total),repay).toFixed(2)}):'';}updateTotal();}}}catch(e){formError(e);}});
form.onsubmit=async e=>{e.preventDefault();const shouldPost=e.submitter?.value==='post';const buttons=[...d.querySelectorAll('[type=submit]')];buttons.forEach(b=>b.disabled=true);d.querySelector('#tradeFormError').textContent='';try{const value=Object.fromEntries(new FormData(form));value.kind=kind;value.idempotency_key=v.idempotency_key;value.lines=[...d.querySelectorAll('.trade-line')].map(r=>Object.fromEntries([...r.querySelectorAll('[data-line]')].map(i=>[i.dataset.line,i.value])));value.payload={additional_cost:value.additional_cost||0,fiscal_ref:value.fiscal_ref||'',due_date:value.due_date||'',category:value.category||'Інше',target_account:value.target_account||null,shift_ids:[...d.querySelectorAll('[name=shift_ids]:checked')].map(x=>Number(x.value)),payments:[...d.querySelectorAll('.trade-payment-row')].map(r=>Object.fromEntries([...r.querySelectorAll('[data-payment]')].map(i=>[i.dataset.payment,i.value])))};const saved=await api(v.id?'vouchers/'+v.id:'vouchers',v.id?'PUT':'POST',value);editing.id=saved.id;v.id=saved.id;if(shouldPost)await api(`vouchers/${saved.id}/post`,'POST',{});d.dataset.dirty='';d.close();await load();await draw();await viewVoucher(saved.id);}catch(e){formError(e);}finally{buttons.forEach(b=>b.disabled=false);}};}
function retailPrice(p){if(p.manualPrice&&p.price!==null&&p.price!==undefined)return Number(p.price);const step=Number(C.rounding??.5);return Math.ceil(Number(p.cost||0)*(1+Number(p.markup??C.defaultMarkup??30)/100)/step-1e-9)*step;}
async function viewVoucher(id){const v=await api('vouchers/'+id),detail=[['Документ',`№ ${v.number}`],['Дата',v.date],['Стан',status[v.status]],['Магазин',name('stores',v.store)],['Склад',name('warehouses',v.warehouse)],['Контрагент',name('parties',v.party)],['Працівник',name('employees',v.employee)],['Сума',amount(v.total)+' грн'],['Собівартість руху',amount(v.cost)+' грн']];let html=`<dl class="trade-detail">${detail.map(([k,val])=>`<div><dt>${k}</dt><dd>${esc(val)}</dd></div>`).join('')}</dl>${v.note?`<p>${esc(v.note)}</p>`:''}${v.reference?`<p>Пов’язаний документ ${button('№ '+v.reference,'view',`data-id="${v.reference}"`)}</p>`:''}${v.payload.fiscal_ref?`<p>Чек ПРРО: ${esc(v.payload.fiscal_ref)}</p>`:''}`;if(v.lines.length)html+=table(['Товар','Кількість','Ціна','Сума','Собівартість'],v.lines.map(l=>[esc(l.name),quantity(l.quantity)+' '+esc(l.unit),amount(l.price)+' грн',amount(l.amount)+' грн',amount(l.cost)+' грн']));if(v.payload.calculation)html+=table(['Зміна','Ставка','Відсоток','Виторг для %','Нараховано'],v.payload.calculation.map(c=>[esc(c.date),amount(Number(c.rate)*Number(c.units))+' грн',quantity(c.percent)+' %',amount(c.basis_amount)+' грн',amount(c.accrued)+' грн']));if(v.cash_movements.length)html+=`<h3 class="trade-section-title">Рух коштів</h3>`+table(['Рахунок','Сума','Операція'],v.cash_movements.map(e=>[esc(name('accounts',e.account)),amount(e.amount)+' грн',e.reversal?'Скасування':'Проведення']));if(v.movements.length)html+=`<details><summary>Складські проведення</summary>${table(['Склад','Партія','Кількість','Вартість'],v.movements.map(m=>[esc(name('warehouses',m.warehouse)),esc(m.lot),quantity(m.quantity),amount(m.value)+' грн']))}</details>`;let actions='';if(v.status==='draft')actions=button('Редагувати','edit-voucher',`data-id="${id}"`)+button('Провести','post-voucher',`data-id="${id}"`,true)+button('Видалити чернетку','delete-voucher',`data-id="${id}"`);if(v.status==='posted'){if(['owner','manager','accountant'].includes(E.role))actions+=button('Скасувати','reverse-voucher',`data-id="${id}"`);if(v.kind==='purchase_order'&&v.lines.some(l=>Number(l.remaining)>0))actions+=button('Створити надходження','from-order',`data-id="${id}" data-kind="receipt"`,true);if(v.kind==='customer_order'&&v.lines.some(l=>Number(l.remaining)>0))actions+=button('Створити продаж','from-order',`data-id="${id}" data-kind="sale"`,true);if(['sale','receipt'].includes(v.kind)&&v.lines.some(l=>Number(l.remaining)>0))actions+=button(v.kind==='sale'?'Повернення покупця':'Повернення постачальнику','from-order',`data-id="${id}" data-kind="${v.kind==='sale'?'customer_return':'supplier_return'}"`);if(Number(v.outstanding)>0&&roleKinds[E.role].includes('payment'))actions+=button('Оплатити борг','pay-debt',`data-id="${id}"`,true);}modal(`${kinds[v.kind]} · № ${v.number}`,html,actions);}
function simpleForm(title,html,fn){const d=modal(title,`<form id="tradeSimpleForm"><div class="trade-form-grid">${html}</div><div class="row trade-section-title"><button class="btn" type="submit">Зберегти</button></div></form>`,'',true);d.querySelector('form').onsubmit=e=>{e.preventDefault();submit(e.target,fn);};}
function workShiftForm(id){const s=E.work_shifts.find(s=>String(s.id)===String(id))||{},e=E.employees.find(e=>e.id===s.employee_id)||E.employees[0];let html=field('Працівник',select('employee',E.employees.filter(e=>e.active),s.employee_id||e?.id,true))+field('Дата',input('date',s.date||date(),'date','required'))+field('Касова зміна',select('cash_shift',E.shifts.map(c=>({id:c.id,name:`№ ${c.id} · ${name('stores',c.store_id)} · ${new Date(c.opened_at).toLocaleDateString('uk-UA')}`})),s.cash_shift_id,true))+field('Кількість змін',num('units',s.units||1))+field('Ставка за зміну, грн',num('shift_rate',s.shift_rate??e?.shift_rate??0))+field('Відсоток від виторгу, %',num('bonus_percent',s.bonus_percent??e?.bonus_percent??0,'0.001','max="100"'))+field('База відсотка',select('bonus_basis',[{id:'store',name:'Виторг магазину за касову зміну'},{id:'personal',name:'Особисті продажі'},{id:'profit',name:'Валовий прибуток'}],s.bonus_basis||e?.bonus_basis||'store',true))+field('Примітка',input('note',s.note||''));simpleForm('Відпрацьована зміна',html,v=>api('work-shifts','POST',{...v,id:s.id}));dialog.querySelector('[name=employee]').onchange=ev=>{const e=E.employees.find(e=>String(e.id)===ev.target.value);if(e&&!s.id){dialog.querySelector('[name=shift_rate]').value=e.shift_rate;dialog.querySelector('[name=bonus_percent]').value=e.bonus_percent;dialog.querySelector('[name=bonus_basis]').value=e.bonus_basis;}};}
async function userList(){const r=await api('users');modal('Доступ працівників',table(['Логін','Роль','Магазин','Стан','Дії'],r.users.map(u=>[esc(u.username),esc(u.profile__role),esc(name('stores',u.profile__store_id)),u.is_active?'Активний':'Заблокований',u.profile__role==='owner'?'Власник':button('Змінити','user-edit',`data-id="${u.id}"`)])),button('Додати користувача','user-edit','',true));window.TradeUsers=r.users;}
function userForm(id){const u=window.TradeUsers?.find(x=>String(x.id)===String(id))||{};simpleForm('Користувач',field('Логін',input('username',u.username||'','text',`required ${u.id?'readonly':''}`))+field(u.id?'Новий пароль (за потреби)':'Пароль',input('password','','password',`minlength="14" autocomplete="new-password" ${u.id?'':'required'}`))+field('Роль',select('role',[{id:'manager',name:'Керівник магазину'},{id:'cashier',name:'Касир'},{id:'warehouse',name:'Склад'},{id:'accountant',name:'Бухгалтер'}],u.profile__role||'cashier',true))+field('Магазин',select('store',E.stores,u.profile__store_id,false,'Усі магазини'))+field('Стан',select('active',[{id:'yes',name:'Активний'},{id:'no',name:'Заблокований'}],u.is_active===false?'no':'yes',true)),v=>api('users','POST',{...v,id:u.id,active:v.active==='yes'}));}
function download(filename,headers,rows){const safe=v=>{let s=String(v??'');if(/^[=+@-]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"';};const data='\uFEFF'+[headers,...rows].map(r=>r.map(safe).join(';')).join('\r\n'),url=URL.createObjectURL(new Blob([data],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);}
function recipeForm(){const recipeRow=r=>`<div class="trade-payment-row">${field('Інгредієнт',`<select data-recipe="product" required>${productOptions(r.product)}</select>`)}${field('Кількість на 1 од.',`<input data-recipe="quantity" type="number" min="0.001" step="0.001" value="${esc(r.quantity||'')}" required>`)}${button('×','remove-recipe','aria-label="Видалити інгредієнт"')}</div>`;simpleForm('Рецептура готового товару',field('Готовий товар',`<select name="product" required>${productOptions('')}</select>`,'wide')+`<p class="trade-caption wide">Кількість кожного інгредієнта в його одиниці обліку на одну одиницю готового товару.</p><div id="tradeRecipeLines" class="wide"></div><div class="wide">${button('Додати інгредієнт','add-recipe')}</div>`,v=>api('recipes','POST',{product:v.product,recipe:[...dialog.querySelectorAll('[data-recipe=product]')].map(i=>({product:i.value,quantity:i.closest('.trade-payment-row').querySelector('[data-recipe=quantity]').value}))}));window.TradeRecipeRow=recipeRow;dialog.querySelector('[name=product]').onchange=e=>{const p=P.find(p=>p.id===e.target.value);dialog.querySelector('#tradeRecipeLines').innerHTML=(p?.recipe||[]).map(recipeRow).join('');};}
async function act(a,el){if(a==='lines-template'){download('Шаблон-залишків.csv',['ID','Кількість','Ціна','Партія','Придатний до'],P.map(p=>[p.id,'',p.cost||0,'','']));return;}if(a==='import-lines'){const picker=document.createElement('input');picker.type='file';picker.accept='.csv,text/csv';picker.onchange=async()=>{if(!picker.files[0])return;try{const data=await api('import-preview','POST',{csv:await picker.files[0].text()});const lines=data.lines.filter(l=>editing.kind==='inventory'||Number(l.quantity)>0);if(!lines.length)throw Error('Для цього документа потрібні товари з ненульовою кількістю.');dialog.querySelector('#tradeLines').innerHTML=lines.map(l=>lineMarkup(editing.kind,l)).join('');updateTotal();dialog.querySelector('#tradeFormError').textContent='';}catch(e){formError(e);}};picker.click();return;}if(a==='recipe'){recipeForm();return;}if(a==='add-recipe'){dialog.querySelector('#tradeRecipeLines').insertAdjacentHTML('beforeend',window.TradeRecipeRow({}));return;}if(a==='remove-recipe'){el.closest('.trade-payment-row').remove();return;}if(a==='close'){if(dialog.dataset.dirty==='1'&&!confirm('Закрити форму без збереження змін?'))return;dialog.close();return;}if(a==='alerts'){const r=await api('alerts','POST',{});await load();await draw();modal('Контроль операцій',`<p>Активних перевірок: ${r.active}. Нових задач: ${r.created}. Закрито після усунення причин: ${r.resolved}.</p><a class="btn" href="#operations/work">Переглянути поточні задачі</a>`);return;}if(a==='refresh'){await load();await draw();return;}if(a==='next'||a==='prev'){listPage+=a==='next'?1:-1;await draw();return;}if(a==='new-voucher'){await voucherForm(el.dataset.kind);return;}if(a==='entity'){entityForm(el.dataset.entity,el.dataset.id,el.dataset.partyKind);return;}if(a==='view'){await viewVoucher(el.dataset.id);return;}if(a==='edit-voucher'){const v=await api('vouchers/'+el.dataset.id);await voucherForm(v.kind,v);return;}if(a==='post-voucher'){await api('vouchers/'+el.dataset.id+'/post','POST',{});await load();await draw();await viewVoucher(el.dataset.id);return;}if(a==='delete-voucher'){simpleForm('Видалення чернетки',`<p class="wide">Видалити чернетку № ${esc(el.dataset.id)}?</p>`,()=>api('vouchers/'+el.dataset.id,'DELETE'));return;}if(a==='reverse-voucher'){simpleForm('Скасування документа',field('Причина',`<textarea name="reason" rows="3" required></textarea>`,'wide'),v=>api('vouchers/'+el.dataset.id+'/reverse','POST',v));return;}if(a==='from-order'){const v=await api('vouchers/'+el.dataset.id);const returning=['customer_return','supplier_return'].includes(el.dataset.kind),returnAmount=v.lines.reduce((n,l)=>n+Number(l.remaining_amount??l.amount),0),refund=Math.max(0,returnAmount-Number(v.outstanding||0));await voucherForm(el.dataset.kind,null,{store:v.store,warehouse:v.warehouse,party:v.party,reference:v.id,payload:returning&&refund>0?{payments:[{account:v.payload?.payments?.[0]?.account||E.accounts.find(a=>a.store_id===v.store)?.id,amount:refund.toFixed(2)}]}:{},lines:v.lines.filter(l=>Number(l.remaining??l.quantity)>0).map(l=>({...l,quantity:l.remaining??l.quantity,lot:'',expiry:''}))});return;}if(a==='pay-debt'){const v=await api('vouchers/'+el.dataset.id);await voucherForm('payment',null,{store:v.store,party:v.party,reference:v.id,amount:v.outstanding});return;}if(a==='add-line'){dialog.querySelector('#tradeLines').insertAdjacentHTML('beforeend',lineMarkup(editing.kind));updateTotal();return;}if(a==='remove-line'){el.closest('.trade-line').remove();updateTotal();return;}if(a==='add-payment'){dialog.querySelector('#tradePayments').insertAdjacentHTML('beforeend',paymentMarkup());return;}if(a==='remove-payment'){el.closest('.trade-payment-row').remove();return;}if(a==='full-payment'){const total=updateTotal();dialog.querySelector('#tradePayments').innerHTML=paymentMarkup({account:E.shifts.find(s=>String(s.id)===dialog.querySelector('[name=shift]').value)?.account_id||E.accounts.find(a=>a.store_id===Number(editing.store))?.id,amount:total.toFixed(2)});return;}if(a==='barcode'){const input=dialog.querySelector('[name=barcode]'),needle=input.value.trim(),p=P.find(p=>p.barcode===needle)||P.find(p=>p.name.toLocaleLowerCase('uk')===needle.toLocaleLowerCase('uk'));if(!p)throw Error('Товар не знайдено. Задайте штрихкод у картці товару.');const row=[...dialog.querySelectorAll('.trade-line')].find(r=>r.querySelector('[data-line=product]').value===p.id);if(row)row.querySelector('[data-line=quantity]').value=Number(row.querySelector('[data-line=quantity]').value)+1;else{const empty=[...dialog.querySelectorAll('.trade-line')].find(r=>!r.querySelector('[data-line=product]').value);empty?.remove();dialog.querySelector('#tradeLines').insertAdjacentHTML('beforeend',lineMarkup('sale',{product:p.id,quantity:1,price:retailPrice(p)}));}input.value='';updateTotal();input.focus();return;}if(a==='shift-open'){simpleForm('Відкриття касової зміни',field('Каса',select('account',E.accounts.filter(a=>a.kind==='cash'),'',true))+field('Працівник',select('employee',E.employees.filter(e=>e.active))),v=>api('shifts','POST',v));return;}if(a==='shift-close'){simpleForm('Закриття касової зміни',field('Порахована готівка, грн',num('counted','','0.01','required'))+field('Примітка',input('note','')),v=>api('shifts','POST',{...v,id:el.dataset.id,action:'close'}));return;}if(a==='work-shift'){workShiftForm(el.dataset.id);return;}if(a==='customer-history'){const r=await api('vouchers?party='+el.dataset.id);modal('Історія: '+name('parties',el.dataset.id),voucherTable(r.items));return;}if(a==='users'){await userList();return;}if(a==='user-edit'){userForm(el.dataset.id);return;}if(a==='audit'){const r=await api('audit');modal('Журнал змін',table(['Час','Користувач','Дія','Об’єкт','Подробиці'],r.events.map(e=>[new Date(e.at).toLocaleString('uk-UA'),esc(e.user__username),esc(e.action),esc(e.subject),`<span class="trade-history">${esc(JSON.stringify(e.detail))}</span>`])));return;}if(a==='period'){simpleForm('Обліковий період',alert('Дата включно закриває редагування й проведення документів. Порожня дата відкриває період; усі зміни записуються в журнал.')+field('Закрити по',input('date',E.closed_through||'','date'))+field('Причина',input('reason','','text','required')),v=>api('period','POST',v));return;}if(a==='fiscal'){simpleForm('Облік чеків ПРРО',alert('Автоматичний зв’язок з ПРРО потребує назви сервісу та налаштування його API. Тут можна вимагати ручне зазначення номера вже виданого фіскального чека.')+field('Номер чека',select('mode',[{id:'optional',name:'Необов’язковий — тільки управлінський облік'},{id:'required',name:'Обов’язковий номер чека ПРРО'}],E.fiscal_required?'required':'optional',true)),v=>api('fiscal','POST',{required:v.mode==='required'}));return;}if(a==='stock-csv'){download('Залишки-'+date()+'.csv',['Товар','Склад','Кількість','Доступно','Од.','Вартість'],stockData.totals.map(x=>[x.name,name('warehouses',x.warehouse),x.quantity,x.available,x.unit,x.value]));return;}if(a==='report-csv'){download('Звіт-'+date()+'.csv',['Показник','Сума, грн'],Object.entries({Виторг:lastReport.revenue,Собівартість:lastReport.cogs,'Валовий прибуток':lastReport.gross_profit,Витрати:lastReport.expenses,Зарплата:lastReport.payroll,'Операційний результат':lastReport.profit,'Чистий рух коштів':lastReport.cash_net}));return;}}
document.addEventListener('click',e=>{const el=e.target.closest('[data-trade]');if(!el)return;e.preventDefault();if(el.disabled)return;el.disabled=true;Promise.resolve(act(el.dataset.trade,el)).catch(formError).finally(()=>{el.disabled=false;});});
document.addEventListener('change',e=>{if(!main().contains(e.target))return;if(e.target.name==='filterStore'){filterStore=e.target.value;listPage=1;draw().catch(errorPanel);}if(e.target.name==='filterStatus'){filterStatus=e.target.value;listPage=1;draw().catch(errorPanel);}});
let searchTimer;document.addEventListener('input',e=>{if(!['stockSearch','partySearch'].includes(e.target.name))return;search=e.target.value;clearTimeout(searchTimer);searchTimer=setTimeout(()=>{const n=e.target.name,pos=e.target.selectionStart;draw().then(()=>{const x=main().querySelector(`[name=${n}]`);if(x){x.focus();x.setSelectionRange(pos,pos);}}).catch(errorPanel);},250);});
document.addEventListener('submit',async e=>{if(e.target.id!=='tradeReportForm')return;e.preventDefault();try{const values=Object.fromEntries(new FormData(e.target));filterStore=values.store;const r=await api('report?'+new URLSearchParams(values));document.getElementById('tradeReportResult').innerHTML=reportContent(r);}catch(e){errorPanel(e);}});
window.addEventListener('beforeunload',e=>{if(dialog?.open&&dialog.dataset.dirty==='1'){e.preventDefault();e.returnValue='';}});
document.addEventListener('click',e=>{if(e.target.closest('a[href^="#"]')&&dialog?.open&&dialog.dataset.dirty==='1'&&!confirm('Перейти без збереження змін?')){e.preventDefault();e.stopImmediatePropagation();}},true);
window.Trade={handles:tab=>tabs.has(tab),mount(tab){if(current===tab)return;if(dialog?.open)dialog.close();current=tab;listPage=1;search='';main().innerHTML='<section class="panel"><p role="status">Завантаження обліку…</p></section>';load().then(draw).catch(errorPanel);},leave(){if(current){current=null;generation++;}if(dialog?.open)dialog.close();}};
})();
